/**
 * The putter's REAL toolpath, from the G-code Fusion posted for the Haas
 * TM-1P, turned into a compact path the opening intro can draw.
 *
 *   node scripts/prep-toolpath.mjs        # assets-src/putter/putter-op1.nc
 *
 * Writes src/scenes/putter/toolpath.ts. Do not edit that file by hand.
 *
 * Coordinates are mapped into the putter mesh's own space (the STL scaled so
 * its 114.3 mm length is 1.0, centred), so the cutter lands on the part:
 *
 *   G-code X (along the length)  -> mesh z
 *   G-code Y (across, MIRRORED)  -> mesh x
 *   G-code Z (0 = stock top)     -> mesh y, from the part's top face down
 *
 * The orientation was chosen by overlaying the finishing pass (Steep and
 * Shallow) on the STL's footprint in all four flips: only this one traces the
 * scoop cavity. The XY offset centres the cutting moves on the part.
 *
 * The path is decimated (every DECIMATE-th move, always keeping each
 * operation's first and last) and quantised to int16, so the intro carries a
 * few tens of KB rather than the 760 KB program.
 */
import { readFile, writeFile } from "node:fs/promises";

const SRC = "assets-src/putter/putter-op1.nc";
const OUT = "src/scenes/putter/toolpath.ts";
const DECIMATE = 5;
const MM_PER_UNIT = 114.3; // the mesh's unit is the part's length
const HY = 25.4 / MM_PER_UNIT / 2; // half the part height, in mesh units
const Q = 50000; // int16 quantisation: +-0.655 mesh units

const text = await readFile(SRC, "utf8");
const tools = new Map(); // "T2" -> "0.25 in flat end mill"
for (const m of text.matchAll(/^\((T\d+) D=([\d.]+) CR=([\d.]+).*- ([a-z ]+)\)$/gm)) {
  tools.set(m[1], `${m[2]} in ${m[4].trim()}`);
}

const moves = []; // [x, y, z, opIndex] in inches
const ops = []; // { name, tool, start }
const cur = { X: 0, Y: 0, Z: 0 };
let opIndex = -1;
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  const opName = /^\(([A-Za-z][A-Za-z ]*\d*)\)$/.exec(line);
  if (opName && !/^Machine$|^Using/.test(opName[1])) {
    // An operation that reuses the last tool has no tool change of its own.
    ops.push({ name: opName[1], tool: ops.at(-1)?.tool ?? "", start: moves.length });
    opIndex = ops.length - 1;
    continue;
  }
  if (line.startsWith("(")) continue;
  const toolChange = /\b(T\d+)\s*M0?6\b/.exec(line);
  if (toolChange && opIndex >= 0) ops[opIndex].tool = tools.get(toolChange[1]) ?? toolChange[1];
  let moved = false;
  for (const m of line.matchAll(/([XYZ])(-?\d*\.?\d+)/g)) {
    cur[m[1]] = parseFloat(m[2]);
    moved = true;
  }
  if (moved && opIndex >= 0) moves.push([cur.X, cur.Y, cur.Z, opIndex]);
}

// Centre the cutting moves (below the stock top) on the part.
const cutting = moves.filter((m) => m[2] < -0.02);
const cx = (Math.min(...cutting.map((m) => m[0])) + Math.max(...cutting.map((m) => m[0]))) / 2;
const cy = (Math.min(...cutting.map((m) => m[1])) + Math.max(...cutting.map((m) => m[1]))) / 2;
const k = 25.4 / MM_PER_UNIT;

const kept = [];
const keptOps = ops.map((o) => ({ ...o, start: 0 }));
moves.forEach((m, i) => {
  const first = i === 0 || moves[i - 1][3] !== m[3];
  const last = i === moves.length - 1 || moves[i + 1][3] !== m[3];
  if (!first && !last && i % DECIMATE) return;
  if (first) keptOps[m[3]].start = kept.length / 3; // point index
  // mesh x (mirrored Y), mesh y (height), mesh z (along X)
  kept.push(-(m[1] - cy) * k, HY + m[2] * k, (m[0] - cx) * k);
});

const q = new Int16Array(kept.length);
kept.forEach((v, i) => (q[i] = Math.max(-32767, Math.min(32767, Math.round(v * Q)))));
const b64 = Buffer.from(q.buffer).toString("base64");

const usedOps = keptOps.filter((o) => o.tool);
await writeFile(
  OUT,
  `/**
 * The putter's real toolpath, generated by scripts/prep-toolpath.mjs from
 * ${SRC} (Haas TM-1P). Do not edit by hand.
 *
 * ${kept.length / 3} points (every ${DECIMATE}th move of ${moves.length}), in the putter mesh's space.
 */
export const TOOLPATH_OPS: { name: string; tool: string; start: number }[] = ${JSON.stringify(
    usedOps.map(({ name, tool, start }) => ({ name, tool, start })),
  )};

const PACKED = "${b64}";

/** x, y, z triples in mesh units. */
export function toolpath(): Float32Array {
  const bin = atob(PACKED);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const q = new Int16Array(bytes.buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i]! / ${Q};
  return out;
}
`,
);
console.log(`${moves.length} moves -> ${kept.length / 3} points, ${(b64.length / 1024).toFixed(1)} KB; ops:`);
for (const o of usedOps) console.log(`  ${o.name.padEnd(20)} ${o.tool}  from point ${o.start}`);
